**Updated GetDefaultBranch flow:**
```
func GetDefaultBranch() string {
    // 1. Environment variable (explicit override)
    if branch := os.Getenv("LOOM_DEFAULT_BRANCH"); branch != "" {
        return branch
    }
    // 2. Auto-detect from worktree topology
    if worktrees, err := DiscoverWorktrees(); err == nil && len(worktrees) >= 2 {
        if detected := DetectIntegrationBranch(worktrees); detected != "" {
            return detected
        }
    }
    // 3. Fallback
    return "main"
}
```

